<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="<?= htmlspecialchars($url('/public/css/app.css'), ENT_QUOTES, 'UTF-8') ?>"><title>Inscription · <?= htmlspecialchars($application['name']) ?></title><body class="outdoor-mode"><?php require __DIR__ . '/../partials/header.php'; ?><main class="auth-page"><h1>Créer un compte</h1><?php if ($message): ?><p class="form-message error"><?= htmlspecialchars($message) ?></p><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><label>Prénom<input name="first_name" required autocomplete="given-name"></label><label>Nom<input name="last_name" required autocomplete="family-name"></label><label>Adresse e-mail<input name="email" type="email" required autocomplete="email"></label><label>Adresse <small>facultative</small><input name="address" maxlength="255" autocomplete="street-address"></label><label>Téléphone <small>facultatif</small><input name="phone" maxlength="30" autocomplete="tel" inputmode="tel"></label><label>Mot de passe <small>12 caractères minimum</small><input name="password" type="password" minlength="12" required autocomplete="new-password"></label><button>Créer mon compte</button></form><p><a href="<?= htmlspecialchars($url('/connexion'), ENT_QUOTES, 'UTF-8') ?>">Déjà inscrit ? Se connecter</a></p></main><?php require __DIR__ . '/../partials/footer.php'; ?></body></html>
